def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    # Generate candidate lucky years of the form d * 10^k
    # Since n can be up to 10^9, and maximum candidate might have few more digits, we can iterate k from 0 to 12
    candidates = []
    for k in range(0, 13):
        for d in range(1, 10):
            candidate = d * (10 ** k)
            if candidate > n:
                candidates.append(candidate)
    # Find the smallest candidate greater than n
    next_lucky_year = min(candidates)
    print(next_lucky_year - n)

if __name__ == '__main__':
    main()

