def solve():
    import sys

    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    s = list(data[1].strip())

    total_g = s.count('G')
    # if no golden trophies or all trophies are golden
    if total_g == 0:
        sys.stdout.write("0")
        return
    if total_g == n:
        sys.stdout.write(str(n))
        return

    # Precompute left: consecutive G's ending at index i
    left = [0] * n
    if s[0] == 'G':
        left[0] = 1
    for i in range(1, n):
        if s[i] == 'G':
            left[i] = left[i - 1] + 1
        else:
            left[i] = 0

    # Precompute right: consecutive G's starting at index i
    right = [0] * n
    if s[-1] == 'G':
        right[-1] = 1
    for i in range(n - 2, -1, -1):
        if s[i] == 'G':
            right[i] = right[i + 1] + 1
        else:
            right[i] = 0

    # Maximum contiguous G's in the original arrangement
    ans = max(left)

    # Consider every silver trophy as a potential swap candidate
    for i in range(n):
        if s[i] == 'S':
            left_count = left[i - 1] if i - 1 >= 0 else 0
            right_count = right[i + 1] if i + 1 < n else 0
            combined = left_count + right_count
            # If there is an extra G somewhere to swap, we can add 1
            if combined < total_g:
                combined += 1
            ans = max(ans, combined)

    sys.stdout.write(str(ans))

if __name__ == '__main__':
    solve()

