def main():
    import sys
    sys.setrecursionlimit(200000)
    data = sys.stdin.read().split()

    # Read first line: n and k
    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # Read main courses
    main_courses = [int(next(it)) for _ in range(k)]

    # prereq[i] stores the list of courses that course i depends on
    prereq = [[] for _ in range(n + 1)]
    for course in range(1, n + 1):
        t = int(next(it))
        # then read t numbers
        for _ in range(t):
            dep = int(next(it))
            prereq[course].append(dep)

    # Find all courses that are required (main + prerequisites, recursively)
    required = set()
    visited = [False] * (n + 1)

    def dfs(u):
        if visited[u]:
            return
        visited[u] = True
        required.add(u)
        for v in prereq[u]:
            dfs(v)

    for course in main_courses:
        dfs(course)

    # Build dependency graph (required courses only) and compute indegrees
    from collections import deque
    graph = {course: [] for course in required}
    indegree = {course: 0 for course in required}

    # If a course i in required depends on a course j (and if j is in required), then add edge j -> i
    for i in required:
        for j in prereq[i]:
            if j in required:
                graph[j].append(i)
                indegree[i] += 1

    # Topological sort (Kahn's Algorithm)
    queue = deque()
    for course in required:
        if indegree[course] == 0:
            queue.append(course)
    order = []
    while queue:
        cur = queue.popleft()
        order.append(cur)
        for nxt in graph[cur]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)

    if len(order) != len(required):
        sys.stdout.write("-1")
    else:
        # Print the number of courses and the order
        out = []
        out.append(str(len(order)))
        out.append(" ".join(map(str, order)))
        sys.stdout.write("\n".join(out))

if __name__ == '__main__':
    main()

