#include <bits/stdc++.h>
using namespace std;

// Explanation of our approach:
// We want to restore a stack-sortable permutation p (that is, 231-avoiding) given its first k elements.
// It is known that any stack-sortable permutation has a unique block (or decomposition) structure:
// Let r1, r2, …, r_m be the positions where a new record (an element larger than every earlier one) occurs.
// Then, for each record r_i, the set of numbers that lie between the previous record (with r0 defined as 0) and r_i
// must be exactly the set {prev+1, prev+2, …, r_i - 1} and, for the lexicographically maximal such permutation, must appear
// in decreasing order.
// For example, if the prefix is [3,2,1] then the first record is 3 (with prev = 0) and so the block must equal [2,1].
// In contrast, a prefix like [3,1,2] is not allowed because after 3 the block should be [2,1] but here it is [1,2].
// Also, if a new record appears while the previous block is incomplete (eg, [2,3,1]), then no valid extension exists.
// After processing the given prefix we complete the block for the last record (if needed) and then complete
// the permutation by appending blocks formed by the remaining numbers. In a valid permutation the missing numbers
// above the current record r must form a contiguous interval [r+1, x] and so we add a block: first x, then the entire
// block [x-1, x-2, …, r+1].
// If at any point the necessary contiguous property fails, we output -1.

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if(!(cin >> n >> k)) return 1;

    vector<int> prefix(k);
    vector<bool> used(n+1,false);
    for (int i = 0; i < k; i++){
        cin >> prefix[i];
        if(prefix[i] < 1 || prefix[i] > n){
            cout << -1;
            return 0;
        }
        used[prefix[i]] = true;
    }

    // Check that the given prefix obeys the block structure.
    // Let prevRecord = 0 and let curRecord = prefix[0]. The expected block for curRecord is the full decreasing sequence of
    // numbers from curRecord-1 down to prevRecord+1. In the prefix each time a number less than curRecord appears it must be the
    // next number in that decreasing sequence.
    int prevRecord = 0; 
    int curRecord = prefix[0];
    vector<int> curBlock; // holds a (partial) block for the current record
    bool valid = true;

    for (int i = 1; i < k; i++){
        int x = prefix[i];
        if(x > curRecord){
            // New record encountered; the block just finished must be exactly the full block:
            // It should equal [curRecord - 1, curRecord - 2, ..., prevRecord + 1].
            vector<int> fullBlock;
            for (int a = curRecord - 1; a > prevRecord; a--){
                fullBlock.push_back(a);
            }
            if(curBlock.size() != fullBlock.size()){
                valid = false;
                break;
            }
            for (size_t j = 0; j < curBlock.size(); j++){
                if(curBlock[j] != fullBlock[j]){
                    valid = false;
                    break;
                }
            }
            if(!valid) break;

            // Update: new record started
            prevRecord = curRecord;
            curRecord = x;
            curBlock.clear();
        } else {
            // x must lie between prevRecord+1 and curRecord-1
            if(x <= prevRecord || x >= curRecord){
                valid = false;
                break;
            }
            // In the lexicographically maximal completion the block must appear in strictly decreasing order
            if(!curBlock.empty() && x >= curBlock.back()){
                valid = false;
                break;
            }
            curBlock.push_back(x);
        }
    }

    if(valid){
        // The current block is not complete yet. Its complete version must be the full decreasing sequence from curRecord-1 down to prevRecord+1.
        vector<int> expected;
        for (int a = curRecord - 1; a > prevRecord; a--){
            expected.push_back(a);
        }
        for (size_t i = 0; i < curBlock.size(); i++){
            if(i >= expected.size() || curBlock[i] != expected[i]){
                valid = false;
                break;
            }
        }
    }

    if(!valid){
        cout << -1;
        return 0;
    }

    // Now, the extension is unique. We will build the answer in two parts:
    // (1) Start with the prefix.
    // (2) Complete the current block for the last record (if it is incomplete), then repeatedly append blocks coming from the missing numbers that are larger than the current record.

    vector<int> ans = prefix;

    // (a) Complete the current block. The full block for current record curRecord is the numbers from curRecord-1 down to prevRecord+1.
    int fullBlockSize = curRecord - 1 - prevRecord; // number of numbers expected
    // Already placed curBlock.size() numbers in the prefix for this block.
    for (int a = curRecord - 1 - (int)curBlock.size(); a > prevRecord; a--){
        if(used[a]){ // should be missing
            valid = false;
            break;
        }
        ans.push_back(a);
        used[a] = true;
    }
    if(!valid){
        cout << -1;
        return 0;
    }

    // (b) Now, we must use up all numbers larger than the current record.
    // In a valid (and thus stack–sortable) permutation, the missing numbers above the current record must be a contiguous interval.
    int cur = curRecord;
    while(cur < n){
        int start = cur + 1;
        if(start > n) break;
        if(used[start]){ // if this number is already used, the structure is violated
            valid = false; break;
        }
        // Check contiguous block: all numbers from cur+1 up to some value x must be missing.
        int x = start;
        while(x <= n && !used[x]){
            x++;
        }
        int newRecord = x - 1; // contiguous missing interval is [cur+1, newRecord]
        // Append the block: first the record newRecord, then the block (should appear in decreasing order) consisting of all numbers from newRecord-1 down to cur+1.
        ans.push_back(newRecord);
        used[newRecord] = true;
        for (int a = newRecord - 1; a >= cur + 1; a--){
            if(used[a]){ valid = false; break; }
            ans.push_back(a);
            used[a] = true;
        }
        if(!valid) break;
        cur = newRecord;
    }

    if(!valid || (int)ans.size() != n){
        cout << -1;
        return 0;
    }

    for (int x : ans) cout << x << " ";
    return 0;
}

