        for _ in range(t):
            dep = int(next(it))
            prereq[course].append(dep)

    # Find all courses that are required (main + prerequisites, recursively)
    required = set()
    visited = [False] * (n + 1)

    def dfs(u):
        if visited[u]:
            return
        visited[u] = True
        required.add(u)
        for v in prereq[u]:
            dfs(v)

    for course in main_courses:
        dfs(course)

