    import sys
    data = sys.stdin.read().split()
    if len(data) < 3:
        return
    a, b, c = map(int, data[:3])

    if c == 0:
        if a == b:
            print('YES')
        else:
            print('NO')
    else:
        # Check if b-a is divisible by c and b is in the correct direction
        if (b - a) % c == 0 and ((c > 0 and b >= a) or (c < 0 and b <= a)):
            print('YES')
        else:
            print('NO')

if __name__ == '__main__':
    main()

